using System.Text.Json.Nodes;

namespace EasyMenu.IntegrationTests.Contract;

/// <summary>
/// Compares the OpenAPI document generated by the API with contracts/openapi.yaml (Constitution II)
/// and returns every divergence as a human-readable message (empty list = conformant).
/// </summary>
/// <remarks>
/// Rules:
/// <list type="bullet">
/// <item>Every generated operation MUST exist in the contract.</item>
/// <item>Every contract operation MUST be implemented, unless marked <c>x-pending: true</c>.</item>
/// <item>An implemented operation still marked <c>x-pending: true</c> is a divergence (remove the flag).</item>
/// <item>Matching operations MUST agree on parameters, request body and response status codes, and on the schemas
/// of every media type declared in the contract (after resolving <c>$ref</c>): properties, type, format,
/// required, nullable, enum, items and additionalProperties.</item>
/// <item><c>allOf</c> members are merged into one flat schema on both sides before comparing (properties and
/// required are unioned; a property declared differently by two members, or any other clash, is a divergence),
/// so a contract using composition matches the flat object ASP.NET Core emits for derived types.</item>
/// </list>
/// Extra media types emitted by MVC formatters (text/plain, text/json, ...) are ignored; only media types declared
/// in the contract are compared. Nullability is normalized across OpenAPI 3.0 (<c>nullable: true</c>) and 3.1
/// (<c>type: [x, "null"]</c> or <c>oneOf/anyOf</c> with a <c>{type: "null"}</c> member).
/// </remarks>
public static class OpenApiContractComparer
{
    public const string PendingExtension = "x-pending";

    private static readonly string[] HttpMethods =
        ["get", "put", "post", "delete", "options", "head", "patch", "trace"];

    public static IReadOnlyList<string> Compare(JsonObject contract, JsonObject generated)
    {
        var divergences = new List<string>();
        var contractOps = ReadOperations(contract);
        var generatedOps = ReadOperations(generated);

        foreach (var (key, generatedOp) in generatedOps)
        {
            if (!contractOps.TryGetValue(key, out var contractOp))
            {
                divergences.Add($"{key}: implemented by the API but not described in contracts/openapi.yaml.");
                continue;
            }

            if (IsPending(contractOp.Operation))
            {
                divergences.Add($"{key}: already implemented but still marked {PendingExtension}: true in the contract — remova x-pending de {key}.");
            }

            new OperationComparison(contract, generated, key, divergences).Compare(contractOp, generatedOp);
        }

        foreach (var (key, contractOp) in contractOps)
        {
            if (!generatedOps.ContainsKey(key) && !IsPending(contractOp.Operation))
            {
                divergences.Add($"{key}: described in the contract (without {PendingExtension}) but not implemented by the API.");
            }
        }

        return divergences;
    }

    private sealed record OperationRef(JsonObject PathItem, JsonObject Operation);

    private static SortedDictionary<string, OperationRef> ReadOperations(JsonObject document)
    {
        var result = new SortedDictionary<string, OperationRef>(StringComparer.Ordinal);
        if (document["paths"] is not JsonObject paths)
        {
            return result;
        }

        foreach (var (path, pathNode) in paths)
        {
            if (pathNode is not JsonObject pathItem)
            {
                continue;
            }

            foreach (var method in HttpMethods)
            {
                if (pathItem[method] is JsonObject operation)
                {
                    result[$"{method.ToUpperInvariant()} {path}"] = new OperationRef(pathItem, operation);
                }
            }
        }

        return result;
    }

    private static bool IsPending(JsonObject operation) =>
        operation[PendingExtension] is JsonValue v && v.TryGetValue<bool>(out var pending) && pending;

    private sealed class OperationComparison(
        JsonObject contractDoc, JsonObject generatedDoc, string operationKey, List<string> divergences)
    {
        private readonly HashSet<(string, string)> _visitedRefs = [];

        public void Compare(OperationRef contract, OperationRef generated)
        {
            CompareParameters(contract, generated);
            CompareRequestBody(
                Resolve(contractDoc, contract.Operation["requestBody"]) as JsonObject,
                Resolve(generatedDoc, generated.Operation["requestBody"]) as JsonObject);
            CompareResponses(contract.Operation["responses"] as JsonObject, generated.Operation["responses"] as JsonObject);
        }

        private void Report(string location, string message) =>
            divergences.Add($"{operationKey} → {location}: {message}");

        private void CompareParameters(OperationRef contract, OperationRef generated)
        {
            var contractParams = ReadParameters(contractDoc, contract);
            var generatedParams = ReadParameters(generatedDoc, generated);

            foreach (var key in contractParams.Keys.Union(generatedParams.Keys).Order(StringComparer.Ordinal))
            {
                var location = $"parameter {key}";
                var inContract = contractParams.TryGetValue(key, out var c);
                var inGenerated = generatedParams.TryGetValue(key, out var g);
                if (!inGenerated)
                {
                    Report(location, "declared in the contract but missing in the API.");
                    continue;
                }

                if (!inContract)
                {
                    Report(location, "exposed by the API but not declared in the contract.");
                    continue;
                }

                CompareFlag(location, "required", IsRequired(c!), IsRequired(g!));
                CompareSchema(location, c!["schema"], g!["schema"]);
            }
        }

        private static Dictionary<string, JsonObject> ReadParameters(JsonObject document, OperationRef op)
        {
            var result = new Dictionary<string, JsonObject>(StringComparer.Ordinal);
            // Path-level parameters first; operation-level ones override them (same name + location).
            foreach (var source in new[] { op.PathItem["parameters"], op.Operation["parameters"] })
            {
                if (source is not JsonArray array)
                {
                    continue;
                }

                foreach (var item in array)
                {
                    if (Resolve(document, item) is JsonObject parameter)
                    {
                        result[$"{parameter["in"]?.GetValue<string>()}:{parameter["name"]?.GetValue<string>()}"] = parameter;
                    }
                }
            }

            return result;
        }

        private static bool IsRequired(JsonObject node) =>
            node["required"] is JsonValue v && v.TryGetValue<bool>(out var required) && required;

        private void CompareRequestBody(JsonObject? contract, JsonObject? generated)
        {
            const string location = "request body";
            if (contract is null && generated is null)
            {
                return;
            }

            if (generated is null)
            {
                Report(location, "declared in the contract but not accepted by the API.");
                return;
            }

            if (contract is null)
            {
                Report(location, "accepted by the API but not declared in the contract.");
                return;
            }

            CompareFlag(location, "required", IsRequired(contract), IsRequired(generated));
            CompareContent(location, contract["content"] as JsonObject, generated["content"] as JsonObject);
        }

        private void CompareResponses(JsonObject? contract, JsonObject? generated)
        {
            var contractCodes = (contract?.Select(kv => kv.Key) ?? []).ToHashSet(StringComparer.Ordinal);
            var generatedCodes = (generated?.Select(kv => kv.Key) ?? []).ToHashSet(StringComparer.Ordinal);

            if (!contractCodes.SetEquals(generatedCodes))
            {
                Report("responses",
                    $"status codes differ — contract [{Join(contractCodes)}], API [{Join(generatedCodes)}]" +
                    $" (missing in API: [{Join(contractCodes.Except(generatedCodes))}];" +
                    $" not in contract: [{Join(generatedCodes.Except(contractCodes))}]).");
            }

            foreach (var code in contractCodes.Intersect(generatedCodes).Order(StringComparer.Ordinal))
            {
                var c = Resolve(contractDoc, contract![code]) as JsonObject;
                var g = Resolve(generatedDoc, generated![code]) as JsonObject;
                CompareContent($"response {code}", c?["content"] as JsonObject, g?["content"] as JsonObject);
            }
        }

        private void CompareContent(string location, JsonObject? contract, JsonObject? generated)
        {
            if (contract is null || contract.Count == 0)
            {
                if (generated is { Count: > 0 })
                {
                    Report(location, $"the API declares a body ({Join(generated.Select(kv => kv.Key))}) but the contract declares none.");
                }

                return;
            }

            foreach (var (mediaType, contractMedia) in contract)
            {
                if (generated?[mediaType] is not JsonObject generatedMedia)
                {
                    Report(location, $"media type '{mediaType}' declared in the contract but missing in the API.");
                    continue;
                }

                CompareSchema($"{location} {mediaType}", contractMedia?["schema"], generatedMedia["schema"]);
            }
        }

        private void CompareFlag(string location, string name, bool contract, bool generated)
        {
            if (contract != generated)
            {
                Report(location, $"'{name}' differs — contract {Bool(contract)}, API {Bool(generated)}.");
            }
        }

        private void CompareSchema(string location, JsonNode? contractNode, JsonNode? generatedNode)
        {
            var contractRef = RefOf(contractNode);
            var generatedRef = RefOf(generatedNode);
            if (contractRef is not null && generatedRef is not null && !_visitedRefs.Add((contractRef, generatedRef)))
            {
                return; // recursive schema already being compared
            }

            var c = Schema.Normalize(contractDoc, contractNode);
            var g = Schema.Normalize(generatedDoc, generatedNode);

            if (c.IsEmpty != g.IsEmpty)
            {
                Report(location, c.IsEmpty
                    ? "the contract declares no schema but the API does."
                    : "the contract declares a schema but the API does not.");
                return;
            }

            foreach (var conflict in c.Conflicts)
            {
                Report(location, $"allOf conflict in the contract — {conflict}");
            }

            foreach (var conflict in g.Conflicts)
            {
                Report(location, $"allOf conflict in the API — {conflict}");
            }

            if (!c.Types.SetEquals(g.Types))
            {
                Report(location, $"type differs — contract {c.TypeText}, API {g.TypeText}.");
            }

            if (c.Format != g.Format)
            {
                Report(location, $"format differs — contract {c.Format ?? "(none)"}, API {g.Format ?? "(none)"}.");
            }

            CompareFlag(location, "nullable", c.Nullable, g.Nullable);

            if (!c.Enum.SetEquals(g.Enum))
            {
                Report(location, $"enum differs — contract [{Join(c.Enum)}], API [{Join(g.Enum)}].");
            }

            if (!c.Required.SetEquals(g.Required))
            {
                Report(location, $"required differs — contract [{Join(c.Required)}], API [{Join(g.Required)}]" +
                    $" (missing in API: [{Join(c.Required.Except(g.Required))}];" +
                    $" not in contract: [{Join(g.Required.Except(c.Required))}]).");
            }

            foreach (var name in c.Properties.Keys.Except(g.Properties.Keys).Order(StringComparer.Ordinal))
            {
                Report($"{location}.{name}", "property declared in the contract but missing in the API.");
            }

            foreach (var name in g.Properties.Keys.Except(c.Properties.Keys).Order(StringComparer.Ordinal))
            {
                Report($"{location}.{name}", "property exposed by the API but not declared in the contract.");
            }

            foreach (var name in c.Properties.Keys.Intersect(g.Properties.Keys).Order(StringComparer.Ordinal))
            {
                CompareSchema($"{location}.{name}", c.Properties[name], g.Properties[name]);
            }

            if (c.Items is not null || g.Items is not null)
            {
                CompareSchema($"{location}[]", c.Items, g.Items);
            }

            CompareAdditionalProperties(location, c.AdditionalProperties, g.AdditionalProperties);
            CompareComposition(location, "oneOf", c.OneOf, g.OneOf);
            CompareComposition(location, "anyOf", c.AnyOf, g.AnyOf);
        }

        private void CompareAdditionalProperties(string location, JsonNode? contract, JsonNode? generated)
        {
            if (contract is JsonObject || generated is JsonObject)
            {
                if (contract is JsonObject && generated is JsonObject)
                {
                    CompareSchema($"{location}{{*}}", contract, generated);
                }
                else
                {
                    Report(location, "additionalProperties differs between contract and API.");
                }

                return;
            }

            // Booleans (or absence): only an explicit 'false' vs 'true/absent' matters.
            var c = contract is JsonValue cv && cv.TryGetValue<bool>(out var cb) ? cb : true;
            var g = generated is JsonValue gv && gv.TryGetValue<bool>(out var gb) ? gb : true;
            CompareFlag(location, "additionalProperties", c, g);
        }

        private void CompareComposition(string location, string keyword, JsonArray? contract, JsonArray? generated)
        {
            var cCount = contract?.Count ?? 0;
            var gCount = generated?.Count ?? 0;
            if (cCount != gCount)
            {
                Report(location, $"{keyword} differs — contract has {cCount} member(s), API has {gCount}.");
                return;
            }

            for (var i = 0; i < cCount; i++)
            {
                CompareSchema($"{location} {keyword}[{i}]", contract![i], generated![i]);
            }
        }

        private static string? RefOf(JsonNode? node) =>
            node is JsonObject obj && obj["$ref"] is JsonValue v ? v.GetValue<string>() : null;
    }

    /// <summary>
    /// A schema with $ref resolved, allOf members merged into a flat schema and nullability folded into
    /// <see cref="Nullable"/>. Clashes found while merging allOf are kept in <see cref="Conflicts"/>.
    /// </summary>
    private sealed class Schema
    {
        public bool IsEmpty { get; private init; }
        public SortedSet<string> Types { get; } = new(StringComparer.Ordinal);
        public bool Nullable { get; private set; }
        public string? Format { get; private set; }
        public HashSet<string> Enum { get; } = new(StringComparer.Ordinal);
        public HashSet<string> Required { get; } = new(StringComparer.Ordinal);
        public Dictionary<string, JsonNode?> Properties { get; } = new(StringComparer.Ordinal);
        public JsonNode? Items { get; private set; }
        public JsonNode? AdditionalProperties { get; private set; }
        public JsonArray? OneOf { get; private set; }
        public JsonArray? AnyOf { get; private set; }
        public List<string> Conflicts { get; } = [];

        public string TypeText => Types.Count == 0 ? "(none)" : string.Join("|", Types);

        public static Schema Normalize(JsonObject document, JsonNode? node, int depth = 0)
        {
            var obj = ResolveChain(document, node);
            if (obj is null)
            {
                return new Schema { IsEmpty = true };
            }

            // OpenAPI 3.1 nullable wrapper: oneOf/anyOf: [{type: "null"}, X] -> X (nullable).
            foreach (var keyword in new[] { "oneOf", "anyOf" })
            {
                if (obj[keyword] is JsonArray members && members.Count == 2 && members.Count(IsNullSchema) == 1)
                {
                    var inner = Normalize(document, members.First(m => !IsNullSchema(m)), depth + 1);
                    inner.Nullable = true;
                    return inner;
                }
            }

            var schema = NormalizeOwn(obj);

            // allOf: merge every member (and the schema's own keywords) into one flat schema, so a contract
            // using composition matches the flat object ASP.NET Core emits for derived types (and vice versa).
            if (obj["allOf"] is JsonArray allOf && allOf.Count > 0)
            {
                if (depth > MaxDepth)
                {
                    throw new InvalidOperationException("allOf nesting too deep (cycle?).");
                }

                var members = allOf.Select(m => Normalize(document, m, depth + 1)).ToList();
                for (var i = 0; i < members.Count; i++)
                {
                    schema.MergeFrom(members[i], $"allOf[{i}]");
                }

                // Sibling 'nullable' (common generator wrapper) or every member nullable.
                schema.Nullable = IsTrue(obj["nullable"]) || HasNullType(obj) || members.All(m => m.Nullable);
            }

            return schema;
        }

        private const int MaxDepth = 32;

        private static bool HasNullType(JsonObject obj) =>
            obj["type"] is JsonArray types && types.Any(t => t is JsonValue v && v.GetValue<string>() == "null");

        /// <summary>Merges an allOf member: properties/required are unioned; any other clash is a conflict.</summary>
        private void MergeFrom(Schema member, string source)
        {
            Conflicts.AddRange(member.Conflicts);

            if (member.Types.Count > 0)
            {
                if (Types.Count == 0)
                {
                    Types.UnionWith(member.Types);
                }
                else if (!Types.SetEquals(member.Types))
                {
                    Conflicts.Add($"{source} has type {member.TypeText} but another member has {TypeText}.");
                }
            }

            Format = MergeValue(Format, member.Format, "format", source);

            if (member.Enum.Count > 0)
            {
                if (Enum.Count == 0)
                {
                    Enum.UnionWith(member.Enum);
                }
                else if (!Enum.SetEquals(member.Enum))
                {
                    Conflicts.Add($"{source} has enum [{Join(member.Enum)}] but another member has [{Join(Enum)}].");
                }
            }

            Required.UnionWith(member.Required);

            foreach (var (name, value) in member.Properties)
            {
                if (Properties.TryGetValue(name, out var existing) && !SameJson(existing, value))
                {
                    Conflicts.Add($"property '{name}' is declared differently by {source} and another member.");
                    continue;
                }

                Properties[name] = value;
            }

            Items = MergeNode(Items, member.Items, "items", source);
            AdditionalProperties = MergeNode(AdditionalProperties, member.AdditionalProperties, "additionalProperties", source);
            OneOf = (JsonArray?)MergeNode(OneOf, member.OneOf, "oneOf", source);
            AnyOf = (JsonArray?)MergeNode(AnyOf, member.AnyOf, "anyOf", source);
        }

        private string? MergeValue(string? current, string? incoming, string keyword, string source)
        {
            if (incoming is not null && current is not null && current != incoming)
            {
                Conflicts.Add($"{source} has {keyword} {incoming} but another member has {current}.");
                return current;
            }

            return current ?? incoming;
        }

        private JsonNode? MergeNode(JsonNode? current, JsonNode? incoming, string keyword, string source)
        {
            if (incoming is not null && current is not null && !SameJson(current, incoming))
            {
                Conflicts.Add($"{source} declares a different {keyword} than another member.");
                return current;
            }

            return current ?? incoming;
        }

        private static bool SameJson(JsonNode? a, JsonNode? b) =>
            (a?.ToJsonString() ?? "null") == (b?.ToJsonString() ?? "null");

        /// <summary>The schema's own keywords, ignoring allOf.</summary>
        private static Schema NormalizeOwn(JsonObject obj)
        {
            var schema = new Schema
            {
                Format = obj["format"]?.GetValue<string>(),
                Items = obj["items"],
                AdditionalProperties = obj["additionalProperties"],
                OneOf = obj["oneOf"] as JsonArray,
                AnyOf = obj["anyOf"] as JsonArray,
                Nullable = IsTrue(obj["nullable"]),
            };

            switch (obj["type"])
            {
                case JsonArray types:
                    foreach (var t in types)
                    {
                        schema.AddType(t?.GetValue<string>());
                    }

                    break;
                case JsonValue type:
                    schema.AddType(type.GetValue<string>());
                    break;
            }

            if (obj["enum"] is JsonArray values)
            {
                foreach (var value in values)
                {
                    if (value is null)
                    {
                        schema.Nullable = true;
                    }
                    else
                    {
                        schema.Enum.Add(value.ToJsonString());
                    }
                }
            }

            if (obj["required"] is JsonArray required)
            {
                foreach (var name in required)
                {
                    schema.Required.Add(name!.GetValue<string>());
                }
            }

            if (obj["properties"] is JsonObject properties)
            {
                foreach (var (name, value) in properties)
                {
                    schema.Properties[name] = value;
                }
            }

            return schema;
        }

        private void AddType(string? type)
        {
            if (type == "null")
            {
                Nullable = true;
            }
            else if (type is not null)
            {
                Types.Add(type);
            }
        }

        private static JsonObject? ResolveChain(JsonObject document, JsonNode? node)
        {
            for (var depth = 0; depth < 32; depth++)
            {
                var resolved = Resolve(document, node);
                if (ReferenceEquals(resolved, node))
                {
                    return node as JsonObject;
                }

                node = resolved;
            }

            throw new InvalidOperationException("$ref chain too deep (cycle?).");
        }

        private static bool IsNullSchema(JsonNode? node) =>
            node is JsonObject obj && obj.Count == 1 && obj["type"] is JsonValue v && v.GetValue<string>() == "null";

        private static bool IsTrue(JsonNode? node) =>
            node is JsonValue v && v.TryGetValue<bool>(out var b) && b;
    }

    /// <summary>Resolves a local <c>$ref</c> (one level). Non-reference nodes are returned unchanged.</summary>
    private static JsonNode? Resolve(JsonObject document, JsonNode? node)
    {
        if (node is not JsonObject obj || obj["$ref"] is not JsonValue refValue)
        {
            return node;
        }

        var reference = refValue.GetValue<string>();
        if (!reference.StartsWith("#/", StringComparison.Ordinal))
        {
            throw new NotSupportedException($"Only local $ref are supported (found '{reference}').");
        }

        JsonNode? current = document;
        foreach (var segment in reference[2..].Split('/'))
        {
            var key = segment.Replace("~1", "/").Replace("~0", "~");
            current = (current as JsonObject)?[key]
                ?? throw new InvalidOperationException($"Unresolvable $ref '{reference}'.");
        }

        return current;
    }

    private static string Join(IEnumerable<string> values) => string.Join(", ", values.Order(StringComparer.Ordinal));

    private static string Bool(bool value) => value ? "true" : "false";
}
